import Foundation

enum SessionConfigKind {
    case defaultKind
    case ephemeral
    case background
}

func storesOnDisk(kind: SessionConfigKind) -> Bool {
    switch kind {
    case .defaultKind:
        return true
    case .ephemeral, .background:
        return false
    }
}
print("Ephemeral stores on disk: \(storesOnDisk(kind: .ephemeral))")

