import Foundation

func validate(responseCode: Int) throws -> String {
    if responseCode == 401 {
        throw NSError(domain: "Auth", code: 401)
    }
    return "Valid"
}
do {
    _ = try validate(responseCode: 401)
    print("Result: success")
} catch {
    print("Result: auth error")
}

