struct NetworkResponseValidator {
    static func validateStatusCode(_ code: Int) -> Bool {
        return (200...299).contains(code)
    }
}

let check1 = NetworkResponseValidator.validateStatusCode(204)
let check2 = NetworkResponseValidator.validateStatusCode(500)
print("Validation result: \(check1 && !check2)")

struct EndpointRequestBuilder {
    func makeRequest(urlString: String, token: String?) -> [String: String] {
        var headers = ["Accept": "application/json"]
        if let token = token {
            headers["Authorization"] = "Bearer \(token)"
        }
        return headers
    }
}

let builder = EndpointRequestBuilder()
let headersWithAuth = builder.makeRequest(urlString: "https://api.com", token: "secret123")
let headersWithoutAuth = builder.makeRequest(urlString: "https://api.com", token: nil)
print("Auth present: \(headersWithAuth["Authorization"] != nil), Auth absent: \(headersWithoutAuth["Authorization"] == nil)")

class SessionTypeSelector {
    func requiresBackgroundDaemon(configurationName: String) -> Bool {
        return configurationName == "background"
    }
}

let selector = SessionTypeSelector()
let checkBg = selector.requiresBackgroundDaemon(configurationName: "background")
let checkDef = selector.requiresBackgroundDaemon(configurationName: "default")
print("Daemon check: \(checkBg && !checkDef)")
